import itertools

n = 9
fixed_edges = [(4,7), (0,7)]

def is_triangle_free(edges, n):
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True
    for i in range(n):
        for j in range(i+1, n):
            if adj[i][j]:
                for k in range(j+1, n):
                    if adj[i][k] and adj[j][k]:
                        return False
    return True

def is_maximal(edges, n):
    if not is_triangle_free(edges, n):
        return False
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True
    for i in range(n):
        for j in range(i+1, n):
            if not adj[i][j]:
                found = False
                for w in range(n):
                    if w != i and w != j and adj[i][w] and adj[j][w]:
                        found = True
                        break
                if not found:
                    return False
    return True

