A = {0,4,1,2}
B = {7,3,5,6,8}
edges = []
for a in A:
    for b in B:
        edges.append((min(a,b), max(a,b)))

print("Number of edges:", len(edges))
print("Triangle-free:", is_triangle_free(edges, 9))
print("Maximal:", is_maximal(edges, 9))
print("Contains fixed edges:", all(e in edges or (e[1],e[0]) in edges for e in fixed_edges))
print("Edges:", sorted(edges))

